import datetime
from typing import Dict, Any, Union
import jwt
from jwt.exceptions import ExpiredSignatureError, InvalidSignatureError, InvalidTokenError

# Secret key used for signing HS256 tokens (should be retrieved from secure environment variables in production)
SECRET_KEY = "your-extremely-secure-and-long-secret-key"
ALGORITHM = "HS256"

def generate_token(user_id: str, roles: list, expires_in_minutes: int = 30) -> str:
    """
    Generates a signed JWT with standard claims (sub, iat, exp) and custom claims (roles).
    """
    now = datetime.datetime.now(datetime.timezone.utc)
    payload = {
        "sub": user_id,                                # Subject (identifies the principal)
        "iat": now,                                    # Issued At
        "exp": now + datetime.timedelta(minutes=expires_in_minutes), # Expiration Time
        "roles": roles                                 # Custom claim for authorization
    }
    return jwt.encode(payload, SECRET_KEY, algorithm=ALGORITHM)

def verify_and_validate_token(token: str, required_role: str = None) -> Dict[str, Any]:
    """
    Verifies the token's signature, validates standard claims (exp, iat),
    and enforces optional custom claim authorization.
    """
    try:
        # PyJWT's decode method automatically validates 'exp' and 'iat' claims,
        # and verifies the cryptographic signature.
        payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])

        # Claim Validation: Verify custom application-level claims (authorization)
        if required_role and required_role not in payload.get("roles", []):
            raise PermissionError(f"Access denied: Missing required role '{required_role}'.")

        return {
            "valid": True,
            "payload": payload
        }

    # Error Handling: Catch specific validation and signature failures
